(function(){'use strict';
const S=window.WeylandRoomSpec,root=document.documentElement;root.classList.add('project-room-demo');const ui=document.createElement('div');ui.id='project-room-ui';ui.setAttribute('aria-label','Concept headquarters project room');ui.innerHTML='<div id="room-disclosure"><strong>WEYLANDAI · VENTURE DISTRICT</strong><small>Concept downtown · level-access streets · upper floors/backdrop visual only</small></div><div id="hq-sign" aria-hidden="true">WEYLANDAI</div><nav id="room-tabs" aria-label="Direct project workspaces"></nav><div id="room-instructions">Walk: WASD / left stick · look: drag / right stick<br>Approach doors to open automatically.<span id="room-door-status"></span></div>';document.body.appendChild(ui);const world=document.createElement('div');world.id='room-world-signs';world.setAttribute('aria-label','Workstation signs');document.body.appendChild(world);world.appendChild(document.getElementById('hq-sign'));const back=document.createElement('button');back.id='room-return';back.textContent='Return to project room';back.addEventListener('click',()=>window.__weylandLowerDossier());document.body.appendChild(back);let latest=null,states=[];
function workspace(id){if(!document.getElementById(id))return false;window.WeylandProductSpace?.close();window.__weylandWorldInput?.clear();document.getElementById('envelope-raise')?.click();const tab=document.querySelector('.wn-flag[data-target="'+id+'"]');if(tab)tab.click();else document.getElementById(id).scrollIntoView({block:'start'});ui.dataset.lastWorkspace=id;return true;}
const tabs=document.getElementById('room-tabs'),stationButtons=new Map();for(const s of S.stations){const b=document.createElement('button');b.type='button';b.dataset.workspace=s.id;b.textContent=s.brand;const small=document.createElement('small');small.textContent=s.name;b.appendChild(small);b.addEventListener('click',()=>workspace(s.id));tabs.appendChild(b);const tag=document.createElement('button');tag.className='room-station';tag.dataset.station=s.id;tag.setAttribute('aria-label','Open '+s.brand+' — '+s.hint);tag.innerHTML='<strong></strong><span></span>';tag.querySelector('strong').textContent=s.brand;tag.querySelector('span').textContent=s.name+(s.id==='contractx'?' · Planned':'');tag.hidden=true;tag.addEventListener('click',()=>workspace(s.id));world.appendChild(tag);stationButtons.set(s.id,tag);}
function rayBox(o,d,b){let a=0,z=Infinity;for(let i=0;i<3;i++){if(Math.abs(d[i])<1e-9){if(o[i]<b.c[i]-b.h[i]||o[i]>b.c[i]+b.h[i])return null;}else{let t1=(b.c[i]-b.h[i]-o[i])/d[i],t2=(b.c[i]+b.h[i]-o[i])/d[i];a=Math.max(a,Math.min(t1,t2));z=Math.min(z,Math.max(t1,t2));if(z<a)return null;}}return a;}
function blockers(){return [...S.solids,...(latest?.scene?.doors||[]).flatMap(d=>d.leaves)];}
function nearest(o,d){let hit=null;for(const b of blockers()){const t=rayBox(o,d,b);if(t!==null&&(!hit||t<hit.t))hit={id:b.id,t}}return hit;}
function view(){const bd=document.querySelector('#stage-backdrop iframe'),cam=latest?.camera;if(!bd||!cam)return null;const r=bd.getBoundingClientRect(),right=[cam.up[1]*cam.direction[2]-cam.up[2]*cam.direction[1],cam.up[2]*cam.direction[0]-cam.up[0]*cam.direction[2],cam.up[0]*cam.direction[1]-cam.up[1]*cam.direction[0]],dot=(a,b)=>a.reduce((n,x,i)=>n+x*b[i],0);return{r,cam,right,project(point){let q=point.map((v,i)=>v-cam.position[i]),z=dot(q,cam.direction);if(z<=.15)return null;return[r.left+(1+dot(q,right)/z/0.76/(latest.viewport[0]/latest.viewport[1]))*r.width/2,r.top+(1-dot(q,cam.up)/z/0.76)*r.height/2]},ray(x,y){let nx=(2*(x-r.left)/r.width-1)*0.76*(latest.viewport[0]/latest.viewport[1]),ny=(1-2*(y-r.top)/r.height)*0.76,d=cam.direction.map((v,i)=>v+right[i]*nx+cam.up[i]*ny),n=Math.hypot(...d);return d.map(v=>v/n)}};}
function transformPlane(el,points){const src=[[0,0],[640,0],[640,90],[0,90]],A=[],b=[];src.forEach(([x,y],i)=>{const[X,Y]=points[i];A.push([x,y,1,0,0,0,-x*X,-y*X],[0,0,0,x,y,1,-x*Y,-y*Y]);b.push(X,Y)});for(let i=0;i<8;i++){let k=i;for(let j=i+1;j<8;j++)if(Math.abs(A[j][i])>Math.abs(A[k][i]))k=j;[A[i],A[k]]=[A[k],A[i]];[b[i],b[k]]=[b[k],b[i]];if(Math.abs(A[i][i])<1e-10)return;let n=A[i][i];for(let j=i;j<8;j++)A[i][j]/=n;b[i]/=n;for(let j=0;j<8;j++){if(j===i)continue;let n=A[j][i];for(let k=i;k<8;k++)A[j][k]-=n*A[i][k];b[j]-=n*b[i];}}el.style.transform='matrix3d('+[b[0],b[3],0,b[6],b[1],b[4],0,b[7],0,0,1,0,b[2],b[5],0,1].join(',')+')';}
function place(e){latest=e.detail;const v=view();states=[];if(!v)return;const admitted=latest.scene?.projectRoom===true;ui.hidden=!admitted;world.hidden=!admitted;for(const s of S.stations){const p=v.project(s.anchor),delta=s.anchor.map((x,i)=>x-v.cam.position[i]),distance=Math.hypot(...delta),hit=nearest(v.cam.position,delta.map(x=>x/distance)),visible=admitted&&p&&distance<8&&p[0]>15&&p[0]<innerWidth-15&&p[1]>180&&p[1]<innerHeight-115&&(!hit||hit.id===s.solid||hit.t>distance-.15);const el=stationButtons.get(s.id);el.hidden=!visible;if(visible){el.style.left=p[0]+'px';el.style.top=p[1]+'px'}states.push({id:s.id,visible:!!visible,projected:p,distance,blockedBy:hit?.id});}const sign=document.getElementById('hq-sign'),corners=[[-3.2,4.8,-.195],[3.2,4.8,-.195],[3.2,3.9,-.195],[-3.2,3.9,-.195]].map(v.project);sign.hidden=v.cam.position[2]>-.2||corners.some(p=>!p);if(!sign.hidden)transformPlane(sign,corners);document.getElementById('room-door-status').textContent=(latest.scene?.doors||[]).map(d=>d.id+': '+d.phase).join(' · ');}
function tap(x,y){if(!root.classList.contains('folder-lowered')||root.classList.contains('product-reading')||!latest?.scene?.projectRoom)return false;const top=document.elementFromPoint(x,y);if(top?.closest?.('.envelope-frame,#dossier-tap,#room-tabs,.room-station'))return false;const v=view();if(!v)return false;const hit=nearest(v.cam.position,v.ray(x,y));if(!hit||hit.t>8)return false;const s=S.stations.find(s=>s.solid===hit.id);return s?workspace(s.id):false;}

const citySigns=[];
for(const b of S.district.buildings){const el=document.createElement('div');el.className='city-sign';el.style.setProperty('--city-brand',b.primary);el.innerHTML='<strong></strong><small></small>';el.querySelector('strong').textContent=b.name;el.querySelector('small').textContent=b.domain;world.appendChild(el);citySigns.push({b,el});}
const toggle=document.createElement('button');toggle.id='district-map-toggle';toggle.textContent='District map & access';ui.appendChild(toggle);const guide=document.createElement('dialog');guide.id='district-guide';guide.innerHTML='<h2>Venture District</h2><p>Concept architecture, verified venture identities. Walk the level-access sidewalks, marked crossings and streets. No moving traffic is simulated.</p><div class="district-map"><div class="block north-west">FilmLine<br>frontage</div><div class="block north">WeylandAI<br>project rooms</div><div class="block north-east">AuthFor<br>frontage</div><div class="avenue">VENTURE AVENUE · MARKED CROSSING</div><div class="block south-west">MobleyBooks<br>frontage</div><div class="block south">Marketingium<br>concept lobby</div></div><p><b>Walkable:</b> district ground, Weyland project/meeting rooms and Marketingium’s concept lobby with automatic doors.</p><p><b>Visual only:</b> other building interiors, upper floors and distant skyline. No inter-venture application links are connected; the six Weyland tabs still open their existing workspace sections.</p><button type="button">Back to district</button>';document.body.appendChild(guide);function closeGuide(){guide.close();root.classList.remove('district-guide-open');document.querySelector('#stage-backdrop iframe')?.contentWindow?.__weylandRoomController?.setEnabled(root.classList.contains('folder-lowered'));window.__weylandWorldInput?.clear();toggle.focus({preventScroll:true})}toggle.addEventListener('click',()=>{window.__weylandWorldInput?.clear();root.classList.add('district-guide-open');document.querySelector('#stage-backdrop iframe')?.contentWindow?.__weylandRoomController?.setEnabled(false);guide.showModal()});guide.querySelector('button').addEventListener('click',closeGuide);guide.addEventListener('cancel',e=>{e.preventDefault();closeGuide()});guide.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeGuide()}},true);
function placeCity(){const v=view();if(!v)return;for(const {b,el}of citySigns){const dx=b.front==='north'?[-1,0,0]:b.front==='west'?[0,0,-1]:[1,0,0],normal=b.front==='north'?[0,0,1]:b.front==='west'?[-1,0,0]:[0,0,-1],c=b.signCenter,d=v.cam.position.map((x,i)=>x-c[i]),front=d.reduce((n,x,i)=>n+x*normal[i],0)>0;let delta=c.map((x,i)=>x-v.cam.position[i]),distance=Math.hypot(...delta),hit=nearest(v.cam.position,delta.map(x=>x/distance));const corners=[[-1,1],[1,1],[1,-1],[-1,-1]].map(([x,y])=>v.project(c.map((n,i)=>n+dx[i]*b.signWidth*.5*x+(i===1?b.signHeight*.5*y:0))));el.hidden=!front||distance>85||corners.some(p=>!p)||(hit&&hit.t<distance-.4);if(!el.hidden)transformPlane(el,corners)}}
window.addEventListener('weyland:world-camera',e=>{place(e);placeCity()});
window.WeylandProjectRoom=Object.freeze({workspace,tap,stations:()=>states.map(s=>({...s})),scene:S});
})();
